CREATE TABLE IF NOT EXISTS daep_csv_field_mappings ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, sis_name TEXT NOT NULL CHECK (sis_name IN ('Skyward', 'Focus', 'PowerSchool', 'Ascender', 'Other')), sis_name_other TEXT, -- If sis_name = 'Other', store custom name field_mappings JSONB NOT NULL, -- Example field_mappings: -- { -- "student_id": "StudentNumber", -- "first_name": "FirstName", -- "last_name": "LastName", -- "incident_number": "IncidentID", -- "start_date": "PlacementStartDate", -- "days_assigned": "DaysAssigned", -- "offense_code": "OffenseCode", -- "home_campus": "HomeCampusName" -- } sample_headers TEXT[], -- Store CSV headers for reference created_by TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(),
UNIQUE(tenant_id) -- One mapping per tenant );
-- Indexes CREATE INDEX idx_csv_mappings_tenant ON daep_csv_field_mappings(tenant_id);
-- RLS ALTER TABLE daep_csv_field_mappings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "daep_csv_field_mappings_tenant_isolation" ON daep_csv_field_mappings FOR ALL USING ( tenant_id IN ( SELECT COALESCE(active_tenant_id, tenant_id) FROM user_profiles WHERE id = auth.uid()::text ) );
