import { getFieldMapping, extractCSVHeadersAndSample } from '@/app/actions/daep/reconciliation';
import { FieldMappingForm } from './components/field-mapping-form';

export default async function CSVMappingPage({
  searchParams,
}: {
  searchParams: { session?: string; detected_sis?: string };
}) {
  const existingMapping = await getFieldMapping();

  // If coming from upload flow, extract headers and sample data from that session
  let csvHeaders: string[] = [];
  let sampleData: Record<string, string>[] = [];

  if (searchParams.session) {
    const result = await extractCSVHeadersAndSample(searchParams.session);
    if (result.success) {
      csvHeaders = result.headers;
      sampleData = result.sampleData;
    }
  }

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-xl font-semibold text-foreground">CSV Field Mapping</h2>
        <p className="text-sm text-muted-foreground mt-1">
          Configure how your SIS export columns map to DAEP fields
        </p>
      </div>

      <FieldMappingForm
        existingMapping={existingMapping}
        csvHeaders={csvHeaders}
        sampleData={sampleData}
        sessionId={searchParams.session}
        detectedSIS={searchParams.detected_sis}
      />
    </div>
  );
}

