// Pattern matching for auto-suggest
const FIELD_PATTERNS: Record<string, string[]> = {
  student_id: ['studentid', 'student_id', 'studentnumber', 'student_number', 'id', 'pupilid', 'stuid'],
  first_name: ['firstname', 'first_name', 'fname', 'first', 'givenname'],
  last_name: ['lastname', 'last_name', 'lname', 'last', 'surname', 'familyname'],
  incident_number: ['incidentid', 'incident_id', 'incidentnumber', 'incident_number', 'incident', 'incnum'],
  start_date: ['startdate', 'start_date', 'placementstart', 'placement_start', 'begindate', 'startdt'],
  days_assigned: ['daysassigned', 'days_assigned', 'days', 'numdays', 'assigneddays', 'dayscnt'],
  offense_code: ['offensecode', 'offense_code', 'offense', 'disciplinecode', 'peimscode', 'code'],
  home_campus: ['homecampus', 'home_campus', 'campus', 'school', 'homeschool', 'campusname'],
  parent_email: ['parentemail', 'parent_email', 'guardianemail', 'email'],
  guardian_phone: ['guardianphone', 'phone', 'parentphone', 'homephone'],
  grade_level: ['gradelevel', 'grade_level', 'grade', 'gradelvl'],
  assigning_campus: ['assigningcampus', 'assigning_campus', 'fromcampus'],
  placement_reason: ['placementreason', 'reason', 'description'],
  mandatory_placement: ['mandatory', 'mandatoryplacement', 'mandatory_placement', 'ismandatory'],
};

/**
 * Auto-suggest field mappings based on CSV header names
 * Returns object mapping DAEP field keys to suggested CSV column names
 */
function autoSuggestMappings(csvHeaders: string[]): Record<string, string> {
  const suggestions: Record<string, string> = {};

  for (const [daepField, patterns] of Object.entries(FIELD_PATTERNS)) {
    const match = csvHeaders.find(header => {
      const normalized = header.toLowerCase().replace(/[^a-z0-9]/g, '');
      return patterns.some(p => normalized.includes(p) || p.includes(normalized));
    });
    if (match) {
      suggestions[daepField] = match;
    }
  }

  return suggestions;
}

// Track which fields were auto-suggested for "Suggested" badge
const [suggestedFields, setSuggestedFields] = useState<Set<string>>(new Set());

// On initial load with headers, apply suggestions
useEffect(() => {
  if (csvHeaders.length > 0 && Object.keys(mappings).length === 0) {
    const suggested = autoSuggestMappings(csvHeaders);
    setMappings(suggested);
    setSuggestedFields(new Set(Object.keys(suggested)));
  }
}, [csvHeaders]);

// In mapping row, show "Suggested" badge:
{suggestedFields.has(field.key) && mappings[field.key] && (
  <Badge variant="outline" className="ml-2 text-xs text-green-600 border-green-200">
    Suggested
  </Badge>
)}

sample-data-preview.code:

interface MappingRowProps {
  field: { key: string; label: string; description: string };
  value: string;
  onChange: (value: string) => void;
  headers: string[];
  sampleData: Record<string, string>[];
  isSuggested: boolean;
  isRequired: boolean;
}

function MappingRow({ field, value, onChange, headers, sampleData, isSuggested, isRequired }: MappingRowProps) {
  // Get sample values for selected column
  const sampleValues = value
    ? sampleData
        .map(row => row[value])
        .filter(Boolean)
        .slice(0, 3)
    : [];

  return (
    <div className="grid gap-4 md:grid-cols-3 items-start py-3 border-b border-border/50 last:border-0">
      {/* Field label + description */}
      <div>
        <div className="flex items-center gap-2">
          <p className="font-medium">{field.label}</p>
          {isRequired && <Badge variant="destructive" className="text-xs">Required</Badge>}
          {isSuggested && value && (
            <Badge variant="outline" className="text-xs text-green-600 border-green-200">
              Suggested
            </Badge>
          )}
        </div>
        <p className="text-sm text-muted-foreground">{field.description}</p>
      </div>

      {/* Arrow indicator */}
      <div className="hidden md:flex items-center justify-center text-muted-foreground">
        <ArrowRight className="h-4 w-4" />
      </div>

      {/* Column dropdown + sample preview */}
      <div className="space-y-1">
        <Select value={value || ''} onValueChange={onChange}>
          <SelectTrigger className={!value && isRequired ? 'border-destructive' : ''}>
            <SelectValue placeholder={isRequired ? 'Select CSV column' : 'Select (optional)'} />
          </SelectTrigger>
          <SelectContent>
            {!isRequired && (
              <SelectItem value="">-- Not mapped --</SelectItem>
            )}
            {headers.map(header => (
              <SelectItem key={header} value={header}>
                {header}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        {/* Sample data preview */}
        {sampleValues.length > 0 && (
          <div className="text-xs text-muted-foreground">
            Sample: {sampleValues.join(', ')}
          </div>
        )}
      </div>
    </div>
  );
}

